"""Synthetic G-code fixtures in both dialects (bbl, prusa), with G2/G3 arcs.

These stand in for the OrcaSlicer slices of design §16.9 that need the Mac
(stringing_towers, overhang60, tall_abs, spire, the fiducial L-bracket).
They are marked synthetic: real slices replace them when the Mac makes them.
Relative extrusion (M83), 1.75 mm filament.
"""
import math

FIL_AREA = math.pi * (1.75 / 2) ** 2

TAGS = {
    "bbl": {"layer": "; CHANGE_LAYER", "z": "; Z_HEIGHT: {z:.3f}", "h": "; LAYER_HEIGHT: {h:.3f}", "feature": "; FEATURE: {f}",
            "width": "; LINE_WIDTH: {w:.3f}", "wipe_start": "; WIPE_START", "wipe_end": "; WIPE_END"},
    "prusa": {"layer": ";LAYER_CHANGE", "z": ";Z:{z:.3f}", "h": ";HEIGHT:{h:.3f}", "feature": ";TYPE:{f}",
              "width": ";WIDTH:{w:.3f}", "wipe_start": ";WIPE_START", "wipe_end": ";WIPE_END"},
}


class Writer:
    def __init__(self, dialect="bbl", temp=220, fan=100, accel=5000):
        self.d = dialect
        self.t = TAGS[dialect]
        self.out = ["; generated by OrcaSlicer 2.5.0 (printloop synthetic fixture)", "; HEADER_BLOCK_START", "; HEADER_BLOCK_END",
                    "G90", "M83", f"M204 S{accel}", f"M104 S{temp}", "G28", "G1 X5 Y5 Z0.3 F6000", "G1 X60 E5 F1200",
                    "; MACHINE_START_GCODE_END"]
        self.x = self.y = 0.0
        self.z = 0.3
        self.h = 0.2
        self.w = 0.42
        self.feature = None
        self.fan = fan
        self.fan_on = False

    def layer(self, z, h=0.2):
        self.out += [self.t["layer"], self.t["z"].format(z=z), self.t["h"].format(h=h)]
        self.out.append(f"G1 Z{z:.3f} F600")
        self.z, self.h = z, h
        if not self.fan_on and self.fan:
            self.out.append(f"M106 S{int(round(self.fan * 2.55))}")
            self.fan_on = True

    def set_fan(self, pct):
        self.out.append(f"M106 S{int(round(pct * 2.55))}" if pct > 0 else "M107")

    def feat(self, name, w=0.42):
        if name != self.feature:
            self.out.append(self.t["feature"].format(f=name))
            self.feature = name
        if w != self.w or True:
            self.out.append(self.t["width"].format(w=w))
            self.w = w

    def _e(self, L):
        return L * self.w * self.h / FIL_AREA

    def travel(self, x, y, f=12000, retract=0.0, wipe=False, zhop=0.0):
        if wipe:
            self.out.append(self.t["wipe_start"])
            self.out.append(f"G1 X{self.x - 0.5:.3f} Y{self.y:.3f} E-{max(retract, 0.2) / 2:.4f} F3000")
            self.x -= 0.5
            self.out.append(self.t["wipe_end"])
        if retract > 0:
            self.out.append(f"G1 E-{retract:.4f} F1800")
        if zhop:
            self.out.append(f"G1 Z{self.z + zhop:.3f} F600")
        self.out.append(f"G1 X{x:.3f} Y{y:.3f} F{f}")
        if zhop:
            self.out.append(f"G1 Z{self.z:.3f} F600")
        if retract > 0:
            self.out.append(f"G1 E{retract:.4f} F1800")
        self.x, self.y = x, y

    def line(self, x, y, speed=50.0):
        L = math.hypot(x - self.x, y - self.y)
        self.out.append(f"G1 X{x:.3f} Y{y:.3f} E{self._e(L):.5f} F{speed * 60:.0f}")
        self.x, self.y = x, y

    def arc(self, x, y, cx, cy, cw=False, speed=50.0):
        r = math.hypot(self.x - cx, self.y - cy)
        a0 = math.atan2(self.y - cy, self.x - cx)
        a1 = math.atan2(y - cy, x - cx)
        sweep = (a0 - a1) % (2 * math.pi) if cw else (a1 - a0) % (2 * math.pi)
        if sweep < 1e-9:
            sweep = 2 * math.pi
        L = r * sweep
        self.out.append(f"{'G2' if cw else 'G3'} X{x:.3f} Y{y:.3f} I{cx - self.x:.4f} J{cy - self.y:.4f} E{self._e(L):.5f} F{speed * 60:.0f}")
        self.x, self.y = x, y

    def rect(self, x0, y0, x1, y1, feature="Outer wall", speed=50.0, travel_kw=None):
        self.feat(feature, self.w)
        self.travel(x0, y0, **(travel_kw or {}))
        self.feat(feature, self.w)
        for x, y in ((x1, y0), (x1, y1), (x0, y1), (x0, y0)):
            self.line(x, y, speed)

    def poly(self, pts, feature="Outer wall", speed=50.0, travel_kw=None):
        self.feat(feature, self.w)
        self.travel(*pts[0], **(travel_kw or {}))
        for x, y in pts[1:] + [pts[0]]:
            self.line(x, y, speed)

    def infill(self, x0, y0, x1, y1, spacing=1.0, speed=50.0, feature="Sparse infill"):
        self.feat(feature, self.w)
        y = y0 + spacing
        flip = False
        first = True
        while y < y1 - spacing / 2:
            a, b = (x1, x0) if flip else (x0, x1)
            if first:
                self.travel(a, y)
                first = False
            else:
                self.line(a, y, speed)
            self.line(b, y, speed)
            y += spacing
            flip = not flip

    def circle(self, cx, cy, r, speed=20.0, feature="Outer wall"):
        self.feat(feature, self.w)
        self.travel(cx + r, cy)
        self.arc(cx - r, cy, cx, cy, speed=speed)
        self.arc(cx + r, cy, cx, cy, speed=speed)

    def text(self):
        return "\n".join(self.out + ["; MACHINE_END_GCODE_START", "M104 S0", "M107", "G28 X"]) + "\n"


def box_layers(w, x0, y0, x1, y1, z_top, h=0.2, speed=30.0, spacing=1.0, inner=True):
    z = h
    while z <= z_top + 1e-9:
        w.layer(z, h)
        w.rect(x0, y0, x1, y1, "Outer wall", speed)
        if inner:
            w.rect(x0 + w.w, y0 + w.w, x1 - w.w, y1 - w.w, "Inner wall", speed)
        w.infill(x0 + 2 * w.w, y0 + 2 * w.w, x1 - 2 * w.w, y1 - 2 * w.w, spacing, speed)
        z = round(z + h, 4)


def cube(dialect="bbl", size=20.0, h=0.2, speed=30.0, temp=220):
    w = Writer(dialect, temp)
    box_layers(w, 100, 100, 100 + size, 100 + size, size, h, speed)
    return w.text()


def towers(dialect="bbl", gap=40.0, height=10.0, retract=0.0, wipe=False, zhop=0.0, temp=220, single=False, h=0.2):
    """Two 10 x 10 mm towers gap mm apart (stringing). single: one tower."""
    w = Writer(dialect, temp)
    z = h
    while z <= height + 1e-9:
        w.layer(z, h)
        for i in range(1 if single else 2):
            x0 = 100 + i * (10 + gap)
            kw = {"retract": retract, "wipe": wipe, "zhop": zhop}
            w.rect(x0, 100, x0 + 10, 110, "Outer wall", 40, travel_kw=kw)
            w.infill(x0 + 0.42, 100.42, x0 + 9.58, 109.58, 0.9, 60)
        z = round(z + h, 4)
    return w.text()


def overhang(dialect="bbl", angle_deg=60.0, height=10.0, h=0.2, fan=100, speed=30.0):
    """A block whose +x wall leans out angle_deg from vertical (0: a box)."""
    w = Writer(dialect, fan=fan)
    shift = h * math.tan(math.radians(angle_deg))
    z, x1 = h, 120.0
    while z <= height + 1e-9:
        w.layer(z, h)
        w.rect(100, 100, x1, 120, "Outer wall", speed)
        w.infill(100.84, 100.84, x1 - 0.84, 119.16, 1.0, 60)
        z = round(z + h, 4)
        x1 += shift
    return w.text()


def tall_thin(dialect="bbl", footprint=(30.0, 4.0), height=60.0, h=0.3, fan=0):
    w = Writer(dialect, temp=250, fan=fan)
    box_layers(w, 100, 100, 100 + footprint[0], 100 + footprint[1], height, h, 40.0, 1.0)
    return w.text()


def spire(dialect="bbl", r=1.0, height=10.0, h=0.2, speed=20.0):
    """A thin round spire printed with G2/G3 arcs (thermal: short layers)."""
    w = Writer(dialect)
    z = h
    while z <= height + 1e-9:
        w.layer(z, h)
        w.circle(110, 110, r, speed)
        z = round(z + h, 4)
    return w.text()


def l_bracket_layers(dialect="bbl", seam=None, h=0.2, place=None):
    """The fiducial L-bracket in G-code space (see fiducial_vertices).
    seam: (x, y) where each outer-wall loop starts; the loop goes round from
    its nearest corner."""
    w = Writer(dialect)
    base = [(0, 0), (40, 0), (40, 15), (38, 15), (38, 21), (30, 21), (30, 15), (6, 15), (6, 15), (0, 15)]
    up = [(0, 0), (6, 0), (6, 15), (0, 15)]

    place = place or (lambda x, y: (100 + x, 100 + y))

    def placed(pts):
        return [place(x, y) for x, y in pts]

    z = h
    while z <= 29.0 + 1e-9:
        w.layer(z, h)
        outline = base if z <= 4.0 + 1e-9 else up
        pts = []
        for p in outline:
            if not pts or pts[-1] != p:
                pts.append(p)
        pts = _inset(placed(pts), 0.21)
        if seam is not None:
            k = min(range(len(pts)), key=lambda i: math.dist(pts[i], seam))
            pts = pts[k:] + pts[:k]
        w.poly(pts, "Outer wall", 50.0)
        # A short inner line, so each layer's outer wall starts a new seam.
        c = place(3.0, 7.5)
        w.feat("Inner wall")
        w.travel(c[0], c[1])
        c2 = place(3.0, 8.5)
        w.line(c2[0], c2[1], 50.0)
        z = round(z + h, 4)
    return w.text()


def _inset(pts, d):
    """Move each corner of a CCW orthogonal polygon in by d."""
    n = len(pts)
    out = []
    for i in range(n):
        a, b, c = pts[i - 1], pts[i], pts[(i + 1) % n]
        e1 = (b[0] - a[0], b[1] - a[1])
        e2 = (c[0] - b[0], c[1] - b[1])
        l1, l2 = math.hypot(*e1), math.hypot(*e2)
        n1 = (-e1[1] / l1, e1[0] / l1)
        n2 = (-e2[1] / l2, e2[0] / l2)
        bx, by = n1[0] + n2[0], n1[1] + n2[1]
        bl = math.hypot(bx, by)
        cos_half = (n1[0] * bx + n1[1] * by) / bl
        k = d / cos_half
        out.append((b[0] + bx / bl * k, b[1] + by / bl * k))
    return out


def fiducial_vertices():
    """Three known vertices of the L-bracket in model coordinates."""
    return [(40.0, 0.0, 0.0), (38.0, 21.0, 0.0), (6.0, 15.0, 29.0)]
